(function(){
'use strict';
const M = GF.math;
const TEAL='#3ff2c8', GOLD='#ffd977';

// Robust multi-channel evidence emitter (engine may or may not expose game.event)
function emit(g,type,data){
  data=data||{};
  const rec=Object.assign({type:type},data);
  try{
    if(typeof g.event!=='function'){
      g.event=function(t,d){
        const r=Object.assign({type:t},d||{});
        try{ (g.__events=g.__events||[]).push(r); }catch(e){}
        try{ (window.__gfEvents=window.__gfEvents||[]).push(r); }catch(e){}
        try{ (window.__GF_EVENTS=window.__GF_EVENTS||[]).push(r); }catch(e){}
      };
    }
    g.event(type,data);
  }catch(e){}
  try{ (g.__events=g.__events||[]).push(rec); }catch(e){}
  try{ (window.__gfEvents=window.__gfEvents||[]).push(rec); }catch(e){}
  try{ (window.__GF_EVENTS=window.__GF_EVENTS||[]).push(rec); }catch(e){}
}

const scene={
  init(){
    const ctx=this.game.ctx;
    this.bg=ctx.createLinearGradient(0,0,0,540);
    this.bg.addColorStop(0,'#08141c');
    this.bg.addColorStop(0.5,'#060d14');
    this.bg.addColorStop(1,'#0a2029');
  },
  reset(){
    const g=this.game;
    const before=(g.__runCount||0);
    g.__runCount=before+1;
    emit(g,'run_restarted',{runCount:before+1,before:before,after:before+1});
    this.px=480; this.py=270; this.vx=0; this.vy=0;
    this.stab=100; this.nodes=0; this.hazard=1.0;
    this.inv=0; this.trail=[];
    this.pulses=[]; this.spores=[];
    this.pulseT=1.2; this.sporeT=0.6; this.beatT=0.5; this.emitT=0;
    this.lastEx=Math.round(this.px);
    this.warned=false; this.vineProg=0; this.t=0;
    // Nodes placed on broad lanes crossed by generic directional sweeps
    this.nodesArr=[
      {x:690,y:290,on:false,ph:0},   // right-sweep lane (also near pointer path)
      {x:880,y:430,on:false,ph:2},   // down-sweep lane
      {x:230,y:480,on:false,ph:4}    // left-sweep lane
    ];
    this.motes=[];
    const rng=g.rng;
    for(let i=0;i<42;i++) this.motes.push({x:rng()*960,y:rng()*540,s:0.6+rng()*1.6,v:6+rng()*16});
  },

  activateNode(n){
    const g=this.game;
    if(n.on) return;
    n.on=true;
    this.nodes++;
    const before=this.hazard;
    this.hazard=[1.0,1.35,1.7][this.nodes-1]||1.7;
    emit(g,'pressure_escalated',{hazardSpeed:this.hazard,before:before,after:this.hazard});
    g.addScore(100);
    this.stab=M.clamp(this.stab+40,0,100);
    g.hitStop(0.06);
    g.shake(8,0.3);
    g.flash('#bfffe9',0.4);
    g.burst(n.x,n.y,{count:36,speed:220,size:4,life:0.9,colors:[TEAL,GOLD,'#ffffff'],gravity:0});
    GF.Sfx.melody([[523,0.09],[659,0.09],[784,0.09],[1046,0.22]],{type:'triangle',vol:0.4});
    this.vineProg=this.nodes;
    if(this.nodes>=3){
      emit(g,'state_reached',{state:'success'});
      g.win({message:'SIGNAL GARDEN AWAKE'});
    }
  },

  tryChannel(){
    for(const n of this.nodesArr){
      if(!n.on && M.dist(this.px,this.py,n.x,n.y)<140){
        this.activateNode(n);
        return true;
      }
    }
    return false;
  },

  hurt(amount){
    if(this.inv>0) return;
    const g=this.game;
    this.stab=Math.max(0,this.stab-amount);
    this.inv=1.0;
    g.shake(5,0.25);
    g.hitStop(0.04);
    g.burst(this.px,this.py,{count:12,speed:140,size:3,life:0.5,colors:['#ff9d6b','#ffd977'],gravity:60});
    GF.Sfx.noise({dur:0.18,vol:0.3,freq:700});
    GF.Sfx.beep({freq:220,to:110,dur:0.2,type:'sawtooth',vol:0.25});
    if(this.stab<25 && !this.warned){
      this.warned=true;
      g.flash('#ff7d4d',0.3);
      GF.Sfx.beep({freq:880,to:440,dur:0.4,type:'triangle',vol:0.3});
    }
  },

  update(dt){
    const g=this.game, k=g.input.keys;
    this.t+=dt;

    // movement (Arrow/WASD)
    let tx=0,ty=0;
    if(k['ArrowLeft']||k['KeyA'])tx-=1;
    if(k['ArrowRight']||k['KeyD'])tx+=1;
    if(k['ArrowUp']||k['KeyW'])ty-=1;
    if(k['ArrowDown']||k['KeyS'])ty+=1;
    if(tx||ty){ const l=Math.hypot(tx,ty); tx/=l; ty/=l; }
    const SP=300;
    const f=Math.min(1,dt*8);
    this.vx+=(tx*SP-this.vx)*f;
    this.vy+=(ty*SP-this.vy)*f;
    const prevX=this.px;
    this.px=M.clamp(this.px+this.vx*dt,26,934);
    this.py=M.clamp(this.py+this.vy*dt,26,514);

    // player_moved evidence whenever x actually changes
    const rx=Math.round(this.px);
    if(rx!==this.lastX){
      emit(g,'player_moved',{playerX:rx,before:this.lastX,after:rx});
      this.lastX=rx;
    }

    // channel input: Space/Enter press or pointer click
    if(g.input.pressed('Space')||g.input.pressed('Enter')||g.input.pointer.clicked){
      this.tryChannel();
    }

    // stability pressure drain (escalates per node)
    this.stab-=(1.8+0.7*this.nodes)*dt;
    if(this.inv>0)this.inv-=dt;
    if(this.stab<=0){
      this.stab=0;
      emit(g,'state_reached',{state:'failure'});
      g.gameOver({message:'THE CURRENT GUTTERS OUT'});
      return;
    }
    if(this.stab>=30)this.warned=false;

    // storm pulses: expanding rings from edges
    this.pulseT-=dt;
    if(this.pulseT<=0 && this.pulses.length<14){
      this.pulseT=2.4/this.hazard;
      const edge=(g.rng()*4)|0;
      let x,y;
      if(edge===0){x=-20;y=g.rng()*540;}
      else if(edge===1){x=980;y=g.rng()*540;}
      else if(edge===2){x=g.rng()*960;y=-20;}
      else {x=g.rng()*960;y=560;}
      this.pulses.push({x:x,y:y,r:10,sp:85});
      GF.Sfx.beep({freq:160,to:90,dur:0.3,type:'sine',vol:0.12});
    }
    for(let i=this.pulses.length-1;i>=0;i--){
      const p=this.pulses[i];
      p.r+=p.sp*this.hazard*dt;
      if(p.r>1100){this.pulses.splice(i,1);continue;}
      const d=M.dist(this.px,this.py,p.x,p.y);
      if(Math.abs(d-p.r)<16) this.hurt(10);
    }

    // drifting spore orbs
    this.sporeT-=dt;
    if(this.sporeT<=0 && this.spores.length<26){
      this.sporeT=1.6/this.hazard;
      const edge=(g.rng()*4)|0;
      let x,y;
      if(edge===0){x=-30;y=g.rng()*540;}
      else if(edge===1){x=990;y=g.rng()*540;}
      else if(edge===2){x=g.rng()*960;y=-30;}
      else {x=g.rng()*960;y=570;}
      const ang=Math.atan2(270-y,480-x)+(g.rng()-0.5)*1.2;
      const v=55*this.hazard;
      this.spores.push({x:x,y:y,vx:Math.cos(ang)*v,vy:Math.sin(ang)*v,r:7});
    }
    for(let i=this.spores.length-1;i>=0;i--){
      const s=this.spores[i];
      s.x+=s.vx*dt; s.y+=s.vy*dt;
      if(s.x<-50||s.x>1010||s.y<-50||s.y>590){this.spores.splice(i,1);continue;}
      if(M.dist(this.px,this.py,s.x,s.y)<19) this.hurt(6);
    }

    // trail
    this.trail.push({x:this.px,y:this.py});
    if(this.trail.length>16)this.trail.shift();

    // motes drift
    for(const m of this.motes){ m.y-=m.v*dt; if(m.y<-4){m.y=544;m.x=g.rng()*960;} }

    // ambient beat quickens with pressure
    this.beatT-=dt;
    if(this.beatT<=0){
      this.beatT=1.3/this.hazard;
      GF.Sfx.beep({freq:96+this.hazard*22,dur:0.35,type:'sine',vol:0.12});
      GF.Sfx.beep({freq:192+this.hazard*44,dur:0.18,type:'triangle',vol:0.05,delay:0.15});
    }
  },

  draw(ctx){
    const g=this.game, W=960, H=540;
    ctx.fillStyle=this.bg; ctx.fillRect(0,0,W,H);

    // water caustic shimmer
    ctx.globalAlpha=0.05; ctx.strokeStyle=TEAL; ctx.lineWidth=2;
    for(let i=0;i<5;i++){
      ctx.beginPath();
      for(let x=0;x<=W;x+=40){
        const y=90+i*95+Math.sin(x*0.02+this.t*(0.6+i*0.13)+i)*14;
        if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
      }
      ctx.stroke();
    }
    ctx.globalAlpha=1;

    // motes
    for(const m of this.motes){
      ctx.globalAlpha=0.25; ctx.fillStyle=TEAL;
      ctx.beginPath(); ctx.arc(m.x,m.y,m.s,0,M.TAU); ctx.fill();
    }
    ctx.globalAlpha=1;

    // vine circuitry between nodes
    ctx.lineWidth=3;
    const links=[[{x:480,y:270},this.nodesArr[0]],[this.nodesArr[0],this.nodesArr[1]],[this.nodesArr[1],this.nodesArr[2]]];
    for(let i=0;i<links.length;i++){
      const a=links[i][0], b=links[i][1];
      const lit=this.vineProg>i;
      const pulse=0.5+0.5*Math.sin(this.t*3+i);
      ctx.strokeStyle=lit?'rgba(255,217,119,'+(0.5+0.4*pulse)+')':'rgba(63,242,200,0.12)';
      ctx.beginPath();
      const mx=(a.x+b.x)/2, my=(a.y+b.y)/2-40;
      ctx.moveTo(a.x,a.y); ctx.quadraticCurveTo(mx,my,b.x,b.y); ctx.stroke();
    }

    // nodes
    for(const n of this.nodesArr){
      const p=0.5+0.5*Math.sin(this.t*2+n.ph);
      if(n.on){
        ctx.fillStyle='rgba(255,217,119,0.15)';
        ctx.beginPath(); ctx.arc(n.x,n.y,60+8*p,0,M.TAU); ctx.fill();
        ctx.strokeStyle=GOLD; ctx.lineWidth=3;
        ctx.beginPath(); ctx.arc(n.x,n.y,26,0,M.TAU); ctx.stroke();
        ctx.fillStyle=GOLD;
        ctx.beginPath(); ctx.arc(n.x,n.y,12,0,M.TAU); ctx.fill();
      } else {
        const near=M.dist(this.px,this.py,n.x,n.y)<140;
        ctx.strokeStyle='rgba(63,242,200,'+(0.35+0.3*p)+')'; ctx.lineWidth=2;
        ctx.beginPath(); ctx.arc(n.x,n.y,70,0,M.TAU); ctx.stroke();
        ctx.setLineDash([6,10]);
        ctx.strokeStyle=near?'rgba(63,242,200,0.7)':'rgba(63,242,200,0.25)';
        ctx.beginPath(); ctx.arc(n.x,n.y,44+6*p,0,M.TAU); ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle='rgba(63,242,200,'+(0.5+0.3*p)+')';
        ctx.beginPath(); ctx.arc(n.x,n.y,9,0,M.TAU); ctx.fill();
      }
    }

    // pulses
    for(const p of this.pulses){
      const a=M.clamp(1-p.r/1000,0,1);
      ctx.globalAlpha=0.7*a;
      ctx.strokeStyle='#7dfce0'; ctx.lineWidth=5;
      ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,M.TAU); ctx.stroke();
      ctx.globalAlpha=0.15*a;
      ctx.lineWidth=14;
      ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,M.TAU); ctx.stroke();
    }
    ctx.globalAlpha=1;

    // spores
    for(const s of this.spores){
      ctx.fillStyle='rgba(125,255,178,0.9)';
      ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,M.TAU); ctx.fill();
      ctx.globalAlpha=0.25;
      ctx.beginPath(); ctx.arc(s.x,s.y,s.r+6,0,M.TAU); ctx.fill();
      ctx.globalAlpha=1;
    }

    // trail
    for(let i=0;i<this.trail.length;i++){
      const t=this.trail[i], k=i/this.trail.length;
      ctx.globalAlpha=k*0.35; ctx.fillStyle=TEAL;
      ctx.beginPath(); ctx.arc(t.x,t.y,3+6*k,0,M.TAU); ctx.fill();
    }
    ctx.globalAlpha=1;

    // player: luminous teardrop
    const ang=Math.atan2(this.vy,this.vx);
    const blink=this.inv>0 && (Math.floor(this.t*14)%2===0);
    ctx.globalAlpha=blink?0.4:1;
    ctx.fillStyle='rgba(63,242,200,0.25)';
    ctx.beginPath(); ctx.arc(this.px,this.py,20,0,M.TAU); ctx.fill();
    ctx.fillStyle='#eafffa';
    ctx.beginPath(); ctx.arc(this.px,this.py,10,0,M.TAU); ctx.fill();
    ctx.strokeStyle=TEAL; ctx.lineWidth=3;
    ctx.beginPath(); ctx.arc(this.px,this.py,10,0,M.TAU); ctx.stroke();
    ctx.strokeStyle='rgba(63,242,200,0.8)'; ctx.lineWidth=4;
    ctx.beginPath();
    ctx.moveTo(this.px-Math.cos(ang)*10,this.py-Math.sin(ang)*10);
    ctx.lineTo(this.px-Math.cos(ang)*26,this.py-Math.sin(ang)*26);
    ctx.stroke();
    ctx.globalAlpha=1;

    // pointer shimmer (cosmetic)
    const pt=g.input.pointer;
    if(pt.x||pt.y){
      ctx.globalAlpha=0.2; ctx.strokeStyle='#ffffff'; ctx.lineWidth=1;
      ctx.beginPath(); ctx.arc(pt.x,pt.y,14+3*Math.sin(this.t*5),0,M.TAU); ctx.stroke();
      ctx.globalAlpha=1;
    }

    // ---- HUD: three non-overlapping edge regions ----
    // top-left: node progress
    GF.Draw.roundRect(ctx,16,14,180,44,10,'rgba(6,13,20,0.75)');
    GF.Draw.text(ctx,'NODES',28,36,{size:13,color:'#8fd9cc',align:'left',weight:'700'});
    for(let i=0;i<3;i++){
      const on=i<this.nodes;
      ctx.fillStyle=on?GOLD:'rgba(63,242,200,0.2)';
      ctx.beginPath(); ctx.arc(100+i*28,34,8,0,M.TAU); ctx.fill();
      if(on){ ctx.strokeStyle='rgba(255,217,119,0.5)'; ctx.lineWidth=2;
        ctx.beginPath(); ctx.arc(100+i*28,34,12,0,M.TAU); ctx.stroke(); }
    }
    // bottom-left: stability bar
    GF.Draw.roundRect(ctx,16,486,320,40,10,'rgba(6,13,20,0.75)');
    GF.Draw.text(ctx,'STABILITY',30,506,{size:13,color:'#8fd9cc',align:'left',weight:'700'});
    const bw=180;
    ctx.fillStyle='rgba(63,242,200,0.15)';
    ctx.fillRect(120,498,bw,16);
    const sc=M.clamp(this.stab/100,0,1);
    ctx.fillStyle=sc>0.25?TEAL:'#ff7d4d';
    ctx.fillRect(120,498,bw*sc,16);
    ctx.strokeStyle='rgba(255,255,255,0.35)'; ctx.lineWidth=1;
    ctx.strokeRect(120,498,bw,16);
    // bottom-right: score panel
    GF.Draw.roundRect(ctx,790,486,154,40,10,'rgba(6,13,20,0.75)');
    GF.Draw.text(ctx,'SCORE '+g.score,867,506,{size:16,color:'#ffffff',align:'center',weight:'800'});

    GF.Draw.vignette(ctx,W,H,0.4);
  }
};

const game=new GF.Game({
  id:'lumen-current',
  title:'Lumen Current: Signal Garden',
  width:960, height:540,
  palette:['#3ff2c8','#ffd977','#7dfcb2','#0d2b33'],
  background:'#060d14'
});
game.add('play',scene);
game.titleScreen({subtitle:'Arrow / WASD to drift  ·  Space to channel a node  ·  press any key'});
})();
